- [ ] **Step 3: Implement the component**

Create `components/outfits/outfit-detail.tsx`. Follow `Fitcheck.dc.html:318-365`: a flat-lay stage, the
`OCCASION · WEATHER` kicker, the serif title, the rust-glyph stylist note, the "In this look" rows, and
a sticky action bar.

```tsx
"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Bookmark } from "lucide-react";
import { toggleWear, toggleFavorite } from "@/app/outfits/[id]/actions";
import { Kicker } from "@/components/ui-fitcheck/kicker";
import { wearLabel } from "@/lib/outfits/wear";

export type DetailPiece = {
  id: string;
  name: string;
  brand: string | null;
  category: string;
  imageUrl: string;
};

export function OutfitDetail({
  outfit,
  pieces,
  worn,
  favorite,
}: {
  outfit: {
    id: string;
    lookName: string;
    occasion: string;
    weatherLabel: string;
    reasoning: string | null;
  };
  pieces: DetailPiece[];
  worn: boolean;
  favorite: boolean;
}) {
  const router = useRouter();
  const [isWorn, setWorn] = useState(worn);
  const [isFav, setFav] = useState(favorite);
  const [pending, start] = useTransition();

  return (
    <div className="flex min-h-dvh flex-1 flex-col">
      <button
        onClick={() => router.back()}
        aria-label="Back"
        className="absolute left-[18px] top-[58px] z-40 grid size-10 place-items-center rounded-full bg-[rgba(20,19,22,0.7)] text-xl text-foreground shadow-[inset_0_0_0_1px_var(--hairline-7)] backdrop-blur-[10px]"
      >
        ‹
      </button>

      <div className="flex-1 overflow-y-auto pb-[130px]">
        <div className="surface-stage relative grid h-[420px] place-items-center">
          <div className="flex flex-wrap items-center justify-center gap-3 p-8">
            {pieces.map((p) => (
              // eslint-disable-next-line @next/next/no-img-element
              <img key={p.id} src={p.imageUrl} alt="" className="max-h-40 object-contain" />
            ))}
          </div>
        </div>

        <div className="px-6 pt-2">
          <Kicker>
            {outfit.occasion} · {outfit.weatherLabel}
          </Kicker>
          <h1 className="mt-2 font-serif text-[34px]/[1.04] text-foreground">{outfit.lookName}</h1>

          {outfit.reasoning && (
            <div className="my-5 flex items-start gap-3 rounded-[14px] bg-gradient-to-br from-[#201b18] to-[#191518] p-[18px] shadow-[inset_0_0_0_1px_rgba(184,106,71,0.2)]">
              <span className="grid size-7 shrink-0 place-items-center rounded-full bg-brand font-serif italic text-canvas">
                f
              </span>
              <p className="font-serif text-lg/[1.45] italic text-[#e4ddcd]">
                &ldquo;{outfit.reasoning}&rdquo;
              </p>
            </div>
          )}

          <Kicker className="mb-3 block">In this look</Kicker>
          <div className="flex flex-col gap-[10px]">
            {pieces.map((p) => (
              <div
                key={p.id}
                className="flex items-center gap-[14px] rounded-[13px] bg-surface-1 px-[14px] py-[11px] shadow-[inset_0_0_0_1px_var(--hairline-2)]"
              >
                <div className="grid size-[46px] shrink-0 place-items-center rounded-[10px] bg-surface-3 p-[7px]">
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img src={p.imageUrl} alt="" className="size-full object-contain" />
                </div>
                <div className="flex-1">
                  {p.brand && <Kicker>{p.brand}</Kicker>}
                  <div className="mt-[2px] text-[14.5px] text-value">{p.name}</div>
                </div>
                <div className="shrink-0 text-[11px] text-muted-dim">{p.category}</div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="sticky bottom-0 z-30 flex gap-3 bg-gradient-to-t from-canvas from-60% to-transparent px-[22px] pb-[30px] pt-[14px]">
        <button
          aria-label="Favourite"
          aria-pressed={isFav}
          disabled={pending}
          onClick={() =>
            start(async () => {
              const { favorite } = await toggleFavorite(outfit.id);
              setFav(favorite);
            })
          }
          className="grid h-[54px] w-14 place-items-center rounded-[14px] bg-surface-2 shadow-[inset_0_0_0_1px_var(--hairline-7)]"
        >
          <Bookmark size={22} className={isFav ? "fill-brand text-brand" : "text-muted-foreground"} />
        </button>
        <button
          disabled={pending}
          onClick={() =>
            start(async () => {
              const { worn: next } = await toggleWear(outfit.id);
              setWorn(next);
            })
          }
          className={`flex-1 rounded-[14px] text-[15.5px] font-semibold transition-colors ${
            isWorn ? "bg-surface-2 text-value" : "bg-foreground text-canvas"
          }`}
        >
          {wearLabel(isWorn)}
        </button>
      </div>
    </div>
  );
}
```

