3	import { WeatherStrip } from "./weather-strip";
4	import { OccasionRow, RefineButton } from "./occasion-row";
5	import { RefineSheet } from "./refine-sheet";
6	import { IndexTabs } from "./index-tabs";
7	import { FlatLay } from "./flat-lay";
8	import { WhyQuote } from "./why-quote";
9	import { Credits } from "./credits";
10	import type { Look, UiOccasion, WeatherPayload } from "@/lib/generator/types";
11	import type { City } from "@/lib/weather/geocode";
12	
13	export type StylistStatus = "loading" | "ok" | "empty" | "error";
14	
15	/**
16	 * An empty result is almost never "add more pieces" — it's one specific gap for
17	 * one specific occasion (e.g. no shoes formal enough for Evening). Naming the gap
18	 * turns a dead end into a next step.
19	 */
20	function emptyCopy(missing: string | null | undefined, occasionLabel: string): string {
21	  switch (missing) {
22	    case "Shoes":
23	      return `No shoes formal enough for ${occasionLabel} — add dressier footwear, or try another occasion.`;
