import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { StylistView } from "../stylist-view";
import type { Look, WeatherPayload } from "@/lib/generator/types";

const weather: WeatherPayload = {
  tempC: 14,
  feelsLikeC: 12,
  condition: "Overcast",
  cityLabel: "Berlin",
  timezone: "Europe/Berlin",
  locationOrigin: "default" as const,
  laterSentence: "Dry through the evening — no extra layer.",
  adviceClause: "no extra layer.",
  laterLabel: "Later",
  hourly: [],
};

const look: Look = {
  id: "o1",
  name: "The Camel",
  why: "the camel coat does the talking",
  anchorIndex: 0,
  worn: false,
  pieces: [
    {
      itemId: "i1",
      category: "Outerwear",
      subcategory: null,
      brand: "Uniqlo U",
      name: "Camel coat",
      colors: [],
      cutoutUrl: "/a.png",
      slot: { xPct: 6, yPct: 8, wPct: 46, hPct: 64, rotationDeg: -5, z: 3 },
    },
  ],
};

const noop = () => {};
const base = {
  weather,
  looks: [] as Look[],
  selectedLook: 0,
  occasion: "everyday" as const,
  cities: [],
  refineOpen: false,
  locating: false,
  geoError: null,
  onOccasion: noop,
  onOpenRefine: noop,
  onCloseRefine: noop,
  onRefineApply: noop,
  onCityChange: noop,
  onCitySearch: noop,
  onSelectLook: noop,
  onRetry: noop,
  onRegenerate: noop,
  onOpenItem: noop,
  reason: "",
};

test("loading (D10): skeleton shown, no outfit image", () => {
  render(<StylistView {...base} status="loading" />);
  expect(screen.getByTestId("stylist-skeleton")).toBeInTheDocument();
  expect(screen.queryAllByRole("img")).toHaveLength(0);
});

test("empty (D10): generic copy when we can't name the gap", () => {
  render(<StylistView {...base} status="empty" />);
  expect(screen.getByText("Add a few more pieces to unlock outfits")).toBeInTheDocument();
});

test("empty: names the missing slot and the occasion instead of a generic nudge", () => {
  render(<StylistView {...base} status="empty" missing="Shoes" occasion="evening" />);
  const body = screen.getByTestId("empty-copy").textContent ?? "";
  expect(body).toMatch(/shoes/i); // WHICH gap
  expect(body).toMatch(/evening/i); // for WHICH occasion
  // and it must not fall back to the vague nudge
  expect(screen.queryByText("Add a few more pieces to unlock outfits")).toBeNull();
});


test("error (D10): the retry control re-invokes onRetry", async () => {
  const onRetry = vi.fn();
  render(<StylistView {...base} status="error" onRetry={onRetry} />);
  await userEvent.click(screen.getByRole("button", { name: /try again/i }));
  expect(onRetry).toHaveBeenCalled();
});

test("ok (D3): the active look's index name and its byline name are the same single string", () => {
  render(<StylistView {...base} status="ok" looks={[look]} />);
  expect(screen.getAllByText("The Camel").length).toBeGreaterThanOrEqual(2); // index tab + why byline
});

// The daily drop (Decision 5): a new set of looks is an explicit choice the
// user makes, never a side effect of browsing between occasions.
test("Regenerate is offered as an explicit action", async () => {
  const onRegenerate = vi.fn();
  render(<StylistView {...base} status="ok" looks={[look]} onRegenerate={onRegenerate} />);
  await userEvent.click(screen.getByRole("button", { name: /regenerate/i }));
  expect(onRegenerate).toHaveBeenCalledTimes(1);
});

// The smart-default "why" (legible intelligence): a quiet label above the looks.
test("the predicted occasion's reason is shown above the looks", () => {
  render(<StylistView {...base} status="ok" looks={[look]} reason="Styled for your work day" />);
  expect(screen.getByText("Styled for your work day")).toBeInTheDocument();
});

"use client";

import { WeatherStrip } from "./weather-strip";
import { OccasionRow, RefineButton } from "./occasion-row";
import { RefineSheet } from "./refine-sheet";
import { IndexTabs } from "./index-tabs";
import { FlatLay } from "./flat-lay";
import { WhyQuote } from "./why-quote";
import { Credits } from "./credits";
import type { Look, UiOccasion, WeatherPayload } from "@/lib/generator/types";
import type { City } from "@/lib/weather/geocode";

export type StylistStatus = "loading" | "ok" | "empty" | "error";

/**
 * An empty result is almost never "add more pieces" — it's one specific gap for
 * one specific occasion (e.g. no shoes formal enough for Evening). Naming the gap
 * turns a dead end into a next step.
 */
function emptyCopy(missing: string | null | undefined, occasionLabel: string): string {
  switch (missing) {
    case "Shoes":
      return `No shoes formal enough for ${occasionLabel} — add dressier footwear, or try another occasion.`;
    case "Tops":
      return `No tops that suit ${occasionLabel} — add one, or try another occasion.`;
    case "Bottoms":
      return `No bottoms that suit ${occasionLabel} — add a pair, or try another occasion.`;
    default:
      return "Add a few more pieces to unlock outfits";
  }
}

export function StylistView(props: {
  status: StylistStatus;
  weather: WeatherPayload | null;
  looks: Look[];
  selectedLook: number;
  occasion: UiOccasion;
  cities: City[];
  refineOpen: boolean;
  /** Required slot that blocked every combo, when status === "empty". */
  missing?: string | null;
  onOccasion: (o: UiOccasion) => void;
  onOpenRefine: () => void;
  onCloseRefine: () => void;
  onRefineApply: (r: { formality: number; lean: string[] }) => void;
  onCityChange: (c: City) => void;
  onCitySearch: (q: string) => void;
  onUseMyLocation?: () => void; // absent when the browser has no geolocation API
  locating: boolean;
  geoError: string | null;
  onSelectLook: (i: number) => void;
  onRetry: () => void;
  onOpenItem: (itemId: string) => void;
  /** Decision 5: the ONLY way to spend an AI call on a day already answered. */
  onRegenerate: () => void;
  /** The legible "why" for the predicted default occasion (empty until seeded). */
  reason?: string;
}) {
  const { status, weather, looks, selectedLook, occasion } = props;
  const look = looks[selectedLook];
  const occLabel = occasion.charAt(0).toUpperCase() + occasion.slice(1);

  return (
    <main className="relative flex flex-1 flex-col overflow-hidden px-[22px] pt-[46px]">
      {/* The legible "why" — a quiet kicker above the title that makes the smart
          default read as intentional. Uses the documented label step. */}
      {props.reason && (
        <p className="mb-1 text-[11px] uppercase tracking-[0.22em] text-muted-dim">{props.reason}</p>
      )}
      <div className="mb-[10px] flex items-center justify-between gap-3">
        <h1 className="font-serif text-[24px] text-foreground">Today&apos;s Looks</h1>
        <RefineButton onRefine={props.onOpenRefine} />
      </div>

      {weather ? (
        <WeatherStrip
          weather={weather}
          cities={props.cities}
          onSearch={props.onCitySearch}
          onCityChange={props.onCityChange}
          onUseMyLocation={props.onUseMyLocation}
          locating={props.locating}
          geoError={props.geoError}
        />
      ) : (
        <div className="h-10 animate-pulse rounded bg-surface-1" />
      )}

      <div className="mt-[11px]">
        <OccasionRow occasion={occasion} onOccasion={props.onOccasion} />
      </div>

      {looks.length > 0 && (
        <div className="mt-[15px]">
          <IndexTabs names={looks.map((l) => l.name)} selected={selectedLook} onSelect={props.onSelectLook} />
        </div>
      )}

      <div className="mt-[16px] flex flex-1 flex-col">
        {status === "loading" && (
          <div data-testid="stylist-skeleton" className="flex flex-1 flex-col gap-4">
            <div className="flex-1 animate-pulse rounded-[16px] bg-surface-1" style={{ minHeight: 200 }} />
            <div className="h-5 w-3/4 animate-pulse rounded bg-surface-1" />
          </div>
        )}

        {status === "empty" && (
          <div className="flex flex-1 flex-col items-center justify-center gap-2 text-center">
            <p className="font-serif text-[20px] text-foreground">Nothing to style yet</p>
            <p data-testid="empty-copy" className="max-w-[30ch] text-sm text-muted-foreground">
              {emptyCopy(props.missing, occLabel)}
            </p>
          </div>
        )}

        {status === "error" && (
          <div className="flex flex-1 flex-col items-center justify-center gap-3 text-center">
            <p className="text-sm text-muted-foreground">Couldn&apos;t reach the stylist.</p>
            <button
              type="button"
              onClick={props.onRetry}
              className="rounded-[12px] bg-foreground px-5 py-2.5 text-sm font-semibold text-canvas"
            >
              Try again
            </button>
          </div>
        )}

        {status === "ok" && look && (
          <>
            <FlatLay look={look} />
            <WhyQuote name={look.name} why={look.why} />
            <Credits pieces={look.pieces} onOpenItem={props.onOpenItem} />
